// 1. Lấy đúng trường dữ liệu từ node AI / HTTP Request
const aiText = $json.response || $json.output || $json.text || "";

if (!aiText.trim()) {
  throw new Error("AI_Phan_tich_Testcase không trả về dữ liệu.");
}

// 2. Loại bỏ Markdown block
let cleanText = aiText
  .replace(/```(?:json)?/gi, "")
  .replace(/```/g, "")
  .trim();

// 3. Chuẩn hóa ký tự điều khiển & dấu ngoặc kép thông minh trước khi parse
cleanText = cleanText
  // Thay thế ký tự xuống dòng thực sự trong chuỗi string thành space hoặc \n an toàn
  .replace(/[\r\n]+/g, " ")
  // Loại bỏ các ký tự điều khiển không in được (ASCII 0-31)
  .replace(/[\u0000-\u001F\u007F-\u009F]/g, "")
  // Chuyển dấu ngoặc kép thông minh/máy học ( smart quotes “ ” ) thành dấu ngoặc kép chuẩn
  .replace(/[\u201C\u201D\u201E\u201F\u2033\u2036]/g, '"')
  // Chuyển dấu nháy đơn thông minh ( ‘ ’ ) thành dấu nháy đơn chuẩn
  .replace(/[\u2018\u2019\u201A\u201B\u2032\u2035]/g, "'");

let parsedData;

try {
  parsedData = JSON.parse(cleanText);
} catch (error) {
  // Sửa lỗi trailing comma (dấu phẩy thừa trước } hoặc ])
  const repairedText = cleanText
    .replace(/,\s*}/g, "}")
    .replace(/,\s*]/g, "]");

  try {
    parsedData = JSON.parse(repairedText);
  } catch (error2) {
    throw new Error(
      "AI trả về JSON không hợp lệ: " +
      error2.message +
      "\n\nRAW CLEANED:\n" +
      cleanText
    );
  }
}

// 4. Chuẩn hóa mảng testcases
if (Array.isArray(parsedData)) {
  parsedData = { testcases: parsedData };
}

// Tự động nhận diện nếu AI trả về key khác như "conditions", "data", "items"
const testcases = parsedData.testcases || parsedData.conditions || parsedData.data || [];

if (!Array.isArray(testcases)) {
  throw new Error('Field "testcases" không phải mảng (Array).');
}

// 5. Hàm format mảng thành chuỗi xuống dòng sạch
function formatArray(value) {
  if (value === null || value === undefined) return "";

  if (typeof value === "string") {
    return value.trim();
  }

  if (Array.isArray(value)) {
    return value
      .filter(x => x !== null && x !== undefined && String(x).trim() !== "")
      .map(x => String(x).trim())
      .join("\n");
  }

  return String(value).trim();
}

// 6. Trả về output cho các node tiếp theo trong n8n
return testcases.map(tc => ({
  json: {
    test_suite:        tc.test_suite        || "General",
    muc_dich:          tc.muc_dich          || tc.coverage || tc.condition || "",
    cac_buoc:          formatArray(tc.cac_buoc || tc.context || tc.preconditions),
    ket_qua_mong_muon: formatArray(tc.ket_qua_mong_muon || tc.expected_behavior_hint)
  }
}));

// Lấy data từ API Figma trả về
const figmaData = $input.first().json;
const documentNode = figmaData.document;

// Lấy thông tin bài toán cũ truyền sang để không bị mất kết nối
const baiToanGoc = $("Switch").item.json; 

// Đệ quy moi móc toàn bộ Text trên giao diện
function extractText(node) {
    let texts = [];
    if (node.type === "TEXT" && node.characters) {
        texts.push(`[${node.name}]: ${node.characters.replace(/\n/g, ' ')}`); 
    }
    if (node.children) {
        for (let child of node.children) {
            texts = texts.concat(extractText(child));
        }
    }
    return texts;
}

const allExtractedText = extractText(documentNode);

// Trả về biến 'data' giống hệt định dạng của nhánh Google Docs
return {
    json: {
        ...baiToanGoc, // Giữ lại tên Bài toán, Link Testcase...
        "data": "DỮ LIỆU GIAO DIỆN TỪ FIGMA:\n" + allExtractedText.join("\n")
    }
};

// 1. Lấy toàn bộ dữ liệu từ node trước đó (nhánh "Chưa làm")
const items = $input.all();
const newItems = [];

// 2. Duyệt qua từng bài toán
for (let i = 0; i < items.length; i++) {
    const item = items[i].json;
    const rawUrls = item["URL"] || "";

    // 3. Tách link: Xử lý cắt chuỗi bằng dấu phẩy (,) hoặc dấu xuống dòng (\n)
    const urlArray = rawUrls.split(/[,\n]+/);

    // 4. Tạo ra các item lẻ cho từng link để node sau dễ đọc
    for (let j = 0; j < urlArray.length; j++) {
        const singleUrl = urlArray[j].trim();

        // Nếu link không bị rỗng thì mới đẩy vào mảng
        if (singleUrl !== "") {
            newItems.push({
                json: {
                    ...item,             // Giữ lại toàn bộ data cũ (Tên bài toán, Link Testcase...)
                    "url_le": singleUrl  // Tạo thêm 1 trường mới chỉ chứa 1 link duy nhất để đọc
                }
            });
        }
    }
}

// 5. Trả về danh sách các link lẻ đã được tách
return newItems;

const items = $input.all();
const grouped = {};

items.forEach(item => {
    const json = item.json;
    const key = json['Bài toán'] || 'Default'; // Gom nhóm theo Tên bài toán

    if (!grouped[key]) {
        // Tạo nhóm mới, giữ lại toàn bộ data gốc
        grouped[key] = { ...json, data: [] };
    }

    // Gom các text tài liệu lẻ vào mảng
    if (json.data) {
        grouped[key].data.push(json.data);
    }
});

// Chạy vòng lặp nối chuỗi mảng thành Text khổng lồ
const results = [];
for (const key in grouped) {
    const finalItem = grouped[key];

    // Chèn Separator siêu đẹp ở đây
    finalItem.data = finalItem.data.join("\n\n--- TÀI LIỆU TIẾP THEO ---\n\n");

    results.push({ json: finalItem });
}

return results;

const items = $input.all();
const baiToanGoc = items[0].json; 

let textContent = `\n\n--- DANH SÁCH API CẦN KIỂM THỬ (BẮT BUỘC ĐỌC) ---\n`;

items.forEach((item) => {
    const data = item.json;
    // Bắt đúng các key từ file Google Sheets của anh
    const tenApi = data["Danh sách api sử dụng "] || "";
    const endpoint = data["col_3"] || data["Đầu api"] || "";
    const moTa = data["col_4"] || data["Mô tả"] || "";

    // Chỉ lấy những dòng có chứa đường link http/api
    if (endpoint.includes("http") || endpoint.includes("api/")) {
        textContent += `\n* Tên API: ${tenApi}\n  - Endpoint: ${endpoint}\n  - Mô tả bổ sung: ${moTa}\n`;
    }
});

return {
    json: {
        "Bài toán": baiToanGoc["Bài toán"],
        "Link Testcase": baiToanGoc["Link Testcase"],
        "Trạng thái": baiToanGoc["Trạng thái"],
        "url_le": baiToanGoc["url_le"],
        "data": textContent
    }
};

// 1. Lấy dữ liệu từ node HTTP Request (AI_phan_tich_bai_toan1)
let aiNodeData = {};
try {
  aiNodeData = $('AI_phan_tich_bai_toan1').first().json;
} catch (e) {
  // Dự phòng nếu tên node có thay đổi hoặc lấy từ node nối trực tiếp phía trước
  aiNodeData = $input.first().json;
}

// 2. Lấy đối tượng dữ liệu đã parse (ưu tiên .data đã được server parse sẵn)
let parsedData = aiNodeData.data || null;
let rawText = aiNodeData.response || aiNodeData.output || aiNodeData.text || "";

// Nếu chưa có parsedData, thử parse từ chuỗi rawText
if (!parsedData && rawText) {
  try {
    // Dọn dẹp các thẻ markdown ```json và ```
    let cleanText = rawText.replace(/```(?:json|markdown|md)?/gi, "").replace(/```/gi, "").trim();
    parsedData = JSON.parse(cleanText);
  } catch (error) {
    parsedData = null;
  }
}

// 3. Ép kiểu và gộp thành 1 đoạn văn bản hoàn chỉnh
let combinedText = "";

if (parsedData && typeof parsedData === 'object') {
  // Gộp các phần theo đúng thứ tự 6 mục nghiệp vụ
  if (parsedData.muc_tieu_tai_lieu) 
      combinedText += "1. MỤC TIÊU TÀI LIỆU\n" + parsedData.muc_tieu_tai_lieu + "\n\n";

  if (parsedData.he_thong_va_api) 
      combinedText += "2. CÁC HỆ THỐNG VÀ API\n" + parsedData.he_thong_va_api + "\n\n";

  if (parsedData.luong_nghiep_vu) 
      combinedText += "3. LUỒNG NGHIỆP VỤ CHÍNH\n" + parsedData.luong_nghiep_vu + "\n\n";

  if (parsedData.bang_du_lieu) 
      combinedText += "4. CÁC BẢNG DỮ LIỆU\n" + parsedData.bang_du_lieu + "\n\n";

  if (parsedData.test_scenarios) 
      combinedText += "5. KỊCH BẢN KIỂM THỬ (TEST SCENARIOS)\n" + parsedData.test_scenarios + "\n\n";

  if (parsedData.rui_ro_va_cau_hoi) 
      combinedText += "6. RỦI RO / ĐIỂM CHƯA RÕ\n" + parsedData.rui_ro_va_cau_hoi + "\n\n";

  // Đề phòng trường hợp Gemini trả về key khác
  if (combinedText === "") {
      for (const key in parsedData) {
          combinedText += `${key.toUpperCase()}:\n${parsedData[key]}\n\n`;
      }
  }
} else {
  // Nếu không parse được JSON, lấy nguyên văn bản phân tích
  combinedText = "Nội dung phân tích:\n\n" + rawText;
}

// 4. Trả về đúng 1 item để ghi vào Google Docs
return [{
  json: {
    final_text: combinedText.trim()
  }
}];

const sheetsData = $input.first().json.sheets;
// Móc lại thông tin Bài toán gốc từ node Switch1
const baiToanGoc = $("phân_luồng_tài_liệu").first().json; 

const results = [];
for (const sheet of sheetsData) {
    results.push({
        json: {
            ...baiToanGoc,
            sheet_name: sheet.properties.title
        }
    });
}
return results;

const body = $input.first().json.body;
const newItems = [];

// Trường hợp 1: Nhận mảng từ nút "Chạy các bài đã chọn"
if (body.danhSachBaiToan && Array.isArray(body.danhSachBaiToan)) {
  body.danhSachBaiToan.forEach(task => {
    newItems.push({
      json: {
        baiToan: task,
        promptAI1: body.promptAI1,
        promptAI2: body.promptAI2
      }
    });
  });
} 
// Trường hợp 2: Nhận chuỗi từ nút "Play" của 1 bài đơn lẻ
else if (body.baiToan) {
  newItems.push({
    json: {
      baiToan: body.baiToan,
      promptAI1: body.promptAI1,
      promptAI2: body.promptAI2
    }
  });
}

return newItems;

let text =
  $json.output ||
  $json.text ||
  $json.content ||
  $json.response ||
  '';

text = text
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

try {
  const parsed = JSON.parse(text);

  return [
    {
      json: parsed
    }
  ];
} catch (error) {
  return [
    {
      json: {
        parse_error: true,
        error_message: error.message,
        raw_output: text
      }
    }
  ];
}

// 1. Lấy đúng trường dữ liệu từ node HTTP Request / AI
const aiText = $json.response || $json.output || $json.text || "";

if (!aiText.trim()) {
  throw new Error("Test_condition_generator không trả về dữ liệu.");
}

// 2. Dọn dẹp Markdown block
let cleanText = aiText
  .replace(/```(?:json)?/gi, "")
  .replace(/```/g, "")
  .trim();

// 3. Xử lý triệt để ký tự điều khiển (Bad control characters) bên trong chuỗi JSON
cleanText = cleanText
  // Thay thế các ký tự xuống dòng thực sự (\n, \r) bên trong JSON thành \\n để không làm vỡ chuỗi
  .replace(/[\r\n]+/g, " ")
  // Loại bỏ các ký tự điều khiển không in được (ASCII 0-31 ngoại trừ không gian chuỗi chuẩn)
  .replace(/[\u0000-\u001F\u007F-\u009F]/g, "")
  // Thay thế các dạng dấu ngoặc kép thông minh/máy học (smart quotes)
  .replace(/[\u201C\u201D\u201E\u201F\u2033\u2036]/g, '"');

try {
  let parsed = JSON.parse(cleanText);

  // Nếu Gemini trả về mảng trực tiếp thay vì object bọc ngoài
  if (Array.isArray(parsed)) {
    parsed = { conditions: parsed };
  }

  // Nếu trả về object bọc trường "coverage_items" thay vì "conditions"
  if (!parsed.conditions && Array.isArray(parsed.coverage_items)) {
    parsed.conditions = parsed.coverage_items;
  }

  if (!Array.isArray(parsed.conditions)) {
    throw new Error('Field "conditions" (hoặc "coverage_items") không phải array.');
  }

  return [
    {
      json: parsed
    }
  ];

} catch (error) {
  throw new Error(
    "Không parse được JSON từ Test_condition_generator: " +
    error.message +
    "\n\nRAW OUTPUT CLEANED:\n" +
    cleanText
  );
}

const items = $input.all();

if (items.length === 0) {
  return [];
}

// ==============================================
// GROUP TESTCASE THEO TEST SUITE
// ==============================================

const groups = new Map();

for (const item of items) {
  const tc = item.json;

  const suite =
    tc.test_suite && String(tc.test_suite).trim()
      ? String(tc.test_suite).trim()
      : "General";

  if (!groups.has(suite)) {
    groups.set(suite, []);
  }

  groups.get(suite).push(tc);
}


// ==============================================
// TẠO OUTPUT:
// Suite
// TC
// TC
// Suite
// TC
// ==============================================

const result = [];

for (const [suite, testcases] of groups.entries()) {

  // Dòng Test Suite
  result.push({
    json: {
      row_type: "suite",
      test_suite: suite,
      muc_dich: suite,
      cac_buoc: "",
      ket_qua_mong_muon: ""
    }
  });

  // Các testcase thuộc suite
  for (const tc of testcases) {
    result.push({
      json: {
        row_type: "testcase",
        test_suite: suite,
        muc_dich: tc.muc_dich || "",
        cac_buoc: tc.cac_buoc || "",
        ket_qua_mong_muon: tc.ket_qua_mong_muon || ""
      }
    });
  }
}

return result;

// 1. Lấy dữ liệu từ node HTTP Request (ưu tiên $json.response)
const aiText = $json.response || $json.output || $json.text || "";

if (!aiText.trim()) {
  throw new Error("Coverage_Expansion không trả về dữ liệu.");
}

// 2. Dọn dẹp thẻ markdown code block và dấu ngoặc kép dạng văn bản
let cleanText = aiText
  .replace(/```(?:json)?/gi, "")
  .replace(/```/g, "")
  .replace(/[“”]/g, '"')
  .trim();

try {
  let parsed = JSON.parse(cleanText);

  // Nếu Gemini trả về mảng trực tiếp thay vì object bọc ngoài
  if (Array.isArray(parsed)) {
    parsed = { coverage_items: parsed };
  }

  if (!Array.isArray(parsed.coverage_items)) {
    throw new Error('Field "coverage_items" không phải array.');
  }

  return [
    {
      json: parsed
    }
  ];

} catch (error) {
  throw new Error(
    "Không parse được JSON Coverage_Expansion: " +
    error.message +
    "\n\nRAW:\n" +
    cleanText
  );
}

